package simulation

import (
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"hackrpi-project/classifier"
	"hackrpi-project/classifier/embeddings"
)

// Exercise the entire JSON -> synthetic HTTP -> embedding text path against the
// golden strings generated by serialize_request from the supplied training code.
func TestSubmitTrainingFixturesMatchesPythonSerialization(t *testing.T) {
	paths, err := filepath.Glob("../classifier/embeddings/testdata/training_examples/*.json")
	if err != nil {
		t.Fatal(err)
	}
	if len(paths) != 6 {
		t.Fatalf("missing training fixtures: %d", len(paths))
	}
	for _, path := range paths {
		t.Run(filepath.Base(path), func(t *testing.T) {
			data, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			expected, err := os.ReadFile(strings.TrimSuffix(path, ".json") + ".txt")
			if err != nil {
				t.Fatal(err)
			}
			called := false
			model := classifier.ClassifierFunc(func(_ context.Context, r *http.Request) (*classifier.Result, error) {
				called = true
				got, err := embeddings.ConvertRequestToEmbedFormat(r)
				if err != nil {
					t.Fatal(err)
				}
				if got != string(expected) {
					t.Fatalf("inference text differs from training\ngot:\n%s\nwant:\n%s", got, expected)
				}
				return &classifier.Result{Riskiness: 0.5}, nil
			})
			h, err := NewHandler(model, &fakeLogger{})
			if err != nil {
				t.Fatal(err)
			}
			r := httptest.NewRequest("POST", "/submit", strings.NewReader(string(data)))
			r.Header.Set("Content-Type", "application/json")
			w := httptest.NewRecorder()
			h.ServeHTTP(w, r)
			if w.Code != 201 || !called {
				t.Fatalf("fixture not evaluated: %d %s", w.Code, w.Body)
			}
		})
	}
}
